using System;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
namespace Downfield {
public partial class GameForm {
 int librarySelection;string playNameDraft="";string renameBack="designer";
 bool NewMenu(){return screen=="bowlsetup"||screen=="bowlcard"||screen=="bowlrules"||screen=="franchisehub"||screen=="club"||screen=="teamhub"||screen=="transfershub"||screen=="staffhub"||screen=="identityhub"||screen=="leaguehub"||screen=="coachhub"||screen=="bindings"||screen=="emergencyqb"||screen=="savedplays"||screen=="savedplay"||screen=="playname";}
 string[] NewRows(){if(screen=="bowlrules")return new string[1];if(screen=="bowlsetup"||screen=="bowlcard")return BowlingRows();switch(screen){case "franchisehub":return new string[]{franchise.Fired?"FIND A JOB":franchise.DraftActive?"ENTER DRAFT":franchise.UserGame==null?"ADVANCE WEEK":"PLAY GAME","TEAM","LEAGUE","COACH","MAIN MENU"};case "club":case "teamhub":return new string[]{"ROSTER","TRANSFERS","STAFF + TRAINING","MONEY + STADIUM","TEAM IDENTITY","BACK"};case "transfershub":return new string[]{"SIGN PLAYERS","TRADE PLAYERS","DRAFT","BACK"};case "staffhub":return new string[]{"COACHES","TRAINING","FACILITIES","BACK"};case "identityhub":return new string[]{"EDIT TEAM","MOVE TEAM","BACK"};case "leaguehub":return new string[]{"SCHEDULE","STANDINGS","PLAYOFFS","STAT LEADERS","NEWS","HISTORY","BACK"};case "coachhub":return new string[]{"MY COACH","TROPHIES","CHAMPIONS","COACHING JOBS","BACK"};case "savedplay":return new string[]{"CALL PLAY","EDIT ROUTES","RENAME","DELETE PLAY","BACK"};case "savedplays":List<string> names=new List<string>();franchise.EnsurePlayLibrary();foreach(DrawnPlay p in franchise.PlayLibrary)names.Add(p.Name);names.Add("BACK");return names.ToArray();case "emergencyqb":List<string> players=new List<string>();foreach(ClubPlayer p in game.EmergencyCandidates())players.Add("#"+p.Number+" "+p.Role+" "+p.Name);return players.ToArray();case "playname":return new string[40];default:return new string[1];}}
 string MenuParent(string page){switch(page){case "club":case "teamhub":case "leaguehub":case "coachhub":return "franchisehub";case "transfershub":case "staffhub":case "identityhub":case "roster":case "stadium":return "teamhub";case "trade":case "freeagents":case "draft":return "transfershub";case "coaches":case "training":case "facilities":return "staffhub";case "brand":case "relocate":return "identityhub";case "standings":case "schedule":case "playoffs":case "leaders":case "news":case "history":return "leaguehub";case "coach":case "trophies":case "champions":case "league":return "coachhub";case "injuries":return "roster";case "savedplay":return "savedplays";case "savedplays":return "calls";case "emergencyqb":return "pause";case "playname":return renameBack;default:return "franchisehub";}}
 void NewBack(){if(screen=="bowlrules"){Open(bowlingMatch==null?"bowlsetup":"bowlcard");return;}if(screen=="bowlsetup"||screen=="bowlcard"){bowlingMatch=null;Open("home");return;}if(screen=="bindings"){capturing=false;Open(controlsBack);}else Open(screen=="franchisehub"?"home":MenuParent(screen));}
 void ActivateNewMenu(){if(screen=="bowlsetup"||screen=="bowlcard"||screen=="bowlrules"){ActivateBowlingMenu();return;}if(screen=="bindings"){ActivateBindings();return;}if(screen=="playname"){string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";if(selection<36&&playNameDraft.Length<18)playNameDraft+=alphabet[selection];else if(selection==36&&playNameDraft.Length<18)playNameDraft+=" ";else if(selection==37&&playNameDraft.Length>0)playNameDraft=playNameDraft.Substring(0,playNameDraft.Length-1);else if(selection==38)CommitPlayName();else if(selection==39)Open(renameBack);return;}if(screen=="emergencyqb"){List<ClubPlayer> list=game.EmergencyCandidates();if(selection<list.Count&&game.ChooseEmergencyQB(list[selection].Id))Open("game");return;}
  if(screen=="savedplays"){if(selection==franchise.PlayLibrary.Count){NewBack();return;}librarySelection=franchise.PlayLibrary[selection].LibraryId;Open("savedplay");return;}if(screen=="savedplay"){DrawnPlay p=franchise.PlayLibrary.Find(x=>x.LibraryId==librarySelection);if(p==null){Open("savedplays");return;}if(selection==0){if(game.State!=Phase.PreSnap){franchise.Notice="Call a saved play before the snap.";return;}game.CustomPlay=p.Copy();game.UseCustom=true;game.RunPlay=false;game.Playbook=p.BasePlay;Open("game");}else if(selection==1){if(game.State!=Phase.PreSnap)return;game.CustomPlay=p.Copy();game.UseCustom=true;OpenDesigner();}else if(selection==2){playNameDraft=p.Name;renameBack="savedplay";Open("playname");selection=38;}else if(selection==3)Confirm("DELETE PLAY",p.Name,"savedplays",()=>franchise.DeleteCustomPlay(librarySelection));else NewBack();return;}
  if(selection==NewRows().Length-1){NewBack();return;}string destination="";switch(screen){case "franchisehub":if(selection==0){if(franchise.Fired)Open("league");else LeagueAction();return;}destination=new string[]{"","teamhub","leaguehub","coachhub"}[selection];break;case "club":case "teamhub":destination=new string[]{"roster","transfershub","staffhub","stadium","identityhub"}[selection];break;case "transfershub":destination=new string[]{"freeagents","trade","draft"}[selection];break;case "staffhub":destination=new string[]{"coaches","training","facilities"}[selection];break;case "identityhub":destination=new string[]{"brand","relocate"}[selection];break;case "leaguehub":destination=new string[]{"schedule","standings","playoffs","leaders","news","history"}[selection];break;case "coachhub":destination=new string[]{"coach","trophies","champions","league"}[selection];break;}if(destination=="brand"){brandMascot=Math.Max(0,Array.IndexOf(Franchise.Mascots,franchise.Club.Mascot));brandPrimary=franchise.Club.Primary;brandSecondary=franchise.Club.Secondary;}if(destination.Length>0)Open(destination);
 }
 bool PlayNameTyping(Keys key){if(screen!="playname")return false;if(key>=Keys.A&&key<=Keys.Z||key>=Keys.D0&&key<=Keys.D9||key==Keys.Space){if(playNameDraft.Length<18)playNameDraft+=key==Keys.Space?' ':(char)(int)key;selection=38;Invalidate();return true;}if(key==Keys.Back){if(playNameDraft.Length>0)playNameDraft=playNameDraft.Substring(0,playNameDraft.Length-1);Invalidate();return true;}return false;}
 void CommitPlayName(){DrawnPlay p=renameBack=="designer"?draftPlay:franchise.PlayLibrary.Find(x=>x.LibraryId==librarySelection);if(p!=null&&franchise.SaveCustomPlay(p,playNameDraft)){designNotice="SAVED TO PLAYBOOK / "+p.Name;Open(renameBack);}else designNotice=franchise.Notice;}
 string CardDetail(string row){switch(row){case "TEAM":return "ROSTER / STAFF / MONEY";case "LEAGUE":return "SCORES / PLAYOFFS / HISTORY";case "COACH":return "PROFILE / TROPHIES / JOBS";case "ROSTER":return "LINEUP / CONTRACTS / HEALTH";case "TRANSFERS":return "SIGN / TRADE / DRAFT";case "STAFF + TRAINING":return "COACHES / XP / FACILITIES";case "MONEY + STADIUM":return "$"+franchise.Credits+"M / FANS "+franchise.Business.Fans+"%";case "TEAM IDENTITY":return "LOGO / COLORS / CITY";case "PLAY GAME":return franchise.UserGame==null?franchise.Stage:"VS "+franchise.Teams[franchise.UserGame.Opponent(franchise.UserTeam)].Mascot;default:return "";}}
 void DrawNewMenu(){if(screen=="bowlsetup"||screen=="bowlcard"||screen=="bowlrules"){DrawBowlingMenu();return;}if(screen=="bindings"){DrawBindings();return;}if(screen=="playname"){string old=coachDraft;coachDraft=playNameDraft;DrawCoachName();Rect(0,0,1280,100,Ink);TextAt("NAME YOUR PLAY",70,42,32,White);coachDraft=old;return;}if(screen=="emergencyqb"){DrawEmergencyMenu();return;}string title=screen=="franchisehub"?"FRANCHISE / "+franchise.Stage:screen=="club"||screen=="teamhub"?"TEAM":screen=="transfershub"?"TEAM / TRANSFERS":screen=="staffhub"?"TEAM / STAFF":screen=="identityhub"?"TEAM / IDENTITY":screen=="leaguehub"?"LEAGUE":screen=="coachhub"?"COACH":screen=="savedplays"?"YOUR PLAYBOOK":"SAVED PLAY";FrontHeader(title);bool office=screen=="franchisehub"||screen=="teamhub"||screen=="club";if(office)OfficeInterior();string[] rows=NewRows();int first=selection/6*6;float origin=office?486:40,width=office?360:584;for(int n=first;n<Math.Min(first+6,rows.Length);n++){float x=origin+(n-first)%2*(width+20),y=179+(n-first)/2*164;bool chosen=selection==n;Rect(x+4,y+5,width,145,Color.FromArgb(21,25,37));Rect(x,y,width,145,chosen?Color.FromArgb(64,91,96):Color.FromArgb(34,43,57));if(chosen){Rect(x,y,width,4,Gold);Rect(x,y,4,145,Gold);}MenuPicture(rows[n],x+20,y+22,48);TextAt(rows[n],x+85,y+34,14,chosen?Gold:White);TextAt(CardDetail(rows[n]),x+20,y+106,10,Muted);HitArea(x,y,width,145,n);}TextAt(Clip(franchise.Notice,94),40,722,11,Mint);if(screen=="savedplay"){DrawnPlay p=franchise.PlayLibrary.Find(x=>x.LibraryId==librarySelection);if(p!=null)TextAt(p.Name,40,140,12,Gold);}if(rows.Length>6)TextAt("PAGE "+(selection/6+1)+" / "+((rows.Length+5)/6),1010,724,11,Muted);}
 void DrawEmergencyMenu(){FrontHeader("CHOOSE EMERGENCY QB");TextAt("ALL QUARTERBACKS ARE OUT. PICK ANY HEALTHY TEAMMATE.",40,138,11,Gold);List<ClubPlayer> list=game.EmergencyCandidates();int first=selection/6*6;for(int i=first;i<Math.Min(first+6,list.Count);i++){ClubPlayer p=list[i];float x=40+(i-first)%2*610,y=180+(i-first)/2*166;Rect(x,y,590,149,selection==i?Color.FromArgb(64,91,96):Color.FromArgb(34,43,57));PlayerPortrait(p,x+15,y+13,92);TextAt("#"+p.Number+" "+p.Name,x+108,y+22,16,White);TextAt(p.Role+" / "+p.OVR+" OVR / ARM "+p.Power,x+108,y+61,12,Mint);TextAt("EMERGENCY PASSING: LOW",x+108,y+103,11,Gold);HitArea(x,y,590,149,i);}TextAt("SELECT TO PUT HIM AT QB / HIS ORIGINAL POSITION MAY BE EMPTY",40,717,11,Muted);}
}
}
